 1	class CuttingRod {
 2	    private static final int EMPTY_ROD_REVENUE = 0;
 3	    private static final int FIRST_SELLABLE_LENGTH = 1;
 4	    private static final int SENTINEL_INDEX = 0;
 5	
 6	    static int cutRod(int[] pricesByLength) {
 7	        validatePrices(pricesByLength);
 8	
 9	        int rodLength = pricesByLength.length - 1;
10	        int[] maxRevenue = new int[rodLength + 1];
11	        maxRevenue[SENTINEL_INDEX] = EMPTY_ROD_REVENUE;
12	
13	        for (int currentLength = FIRST_SELLABLE_LENGTH; currentLength <= rodLength; currentLength++) {
14	            maxRevenue[currentLength] = bestRevenueForLength(pricesByLength, maxRevenue, currentLength);
15	        }
16	
17	        return maxRevenue[rodLength];
18	    }
19	
20	    private static void validatePrices(int[] pricesByLength) {
21	        if (pricesByLength == null || pricesByLength.length == 0) {
22	            throw new IllegalArgumentException("pricesByLength must include a sentinel value at index 0");
23	        }
24	    }
25	
26	    private static int bestRevenueForLength(int[] pricesByLength, int[] maxRevenue, int currentLength) {
27	        int bestRevenue = EMPTY_ROD_REVENUE;
28	
29	        for (int firstCutLength = FIRST_SELLABLE_LENGTH; firstCutLength <= currentLength; firstCutLength++) {
30	            int remainingLength = currentLength - firstCutLength;
31	            int revenue = pricesByLength[firstCutLength] + maxRevenue[remainingLength];
32	            bestRevenue = Math.max(bestRevenue, revenue);
33	        }
34	
35	        return bestRevenue;
36	    }
